function renderQuestion(){const x=q[index];if(!x)return;document.querySelector('#question-number').textContent=(index+1)+' / 10';document.querySelector('#level').textContent=dict().level[x.l];document.querySelector('#question').textContent=x.q[lang()];const box=document.querySelector('#answers');box.innerHTML='';x.a.forEach((answer,i)=>{const b=document.createElement('button');b.textContent=Array.isArray(answer)?answer[lang()]:answer;b.addEventListener('click',()=>choose(i,b));box.appendChild(b)});document.querySelector('#feedback').textContent='';document.querySelector('#feedback').className='';document.querySelector('#next').hidden=true;answered=false}
function choose(choice,button){if(answered)return;answered=true;const x=q[index],ok=choice===x.c;if(ok)score++;document.querySelector('#score').textContent=score;[...document.querySelectorAll('#answers button')].forEach((b,i)=>{b.disabled=true;if(i===x.c)b.classList.add('correct-answer')});if(!ok)button.classList.add('wrong-answer');const f=document.querySelector('#feedback');f.textContent=(ok?dict().correct:dict().wrong)+' '+x.e[lang()];f.className=ok?'correct':'wrong';const next=document.querySelector('#next');next.textContent=index===9?dict().finish:dict().next;next.hidden=false}
function next(){if(index<9){index++;renderQuestion()}else{document.querySelector('#question-card').hidden=true;const result=document.querySelector('#result');result.hidden=false;document.querySelector('#result-title').textContent=dict().resultTitle;document.querySelector('#result-text').textContent=score+'/10 — '+(score>=8?dict().resultGood:score>=5?dict().resultMid:dict().resultLow);document.querySelector('#restart').textContent=dict().restart}}
function restart(){index=0;score=0;document.querySelector('#score').textContent='0';document.querySelector('#result').hidden=true;document.querySelector('#question-card').hidden=false;renderQuestion()}
