let fIndex=0,fScore=0,fAnswered=false;
function renderFactor(){const x=factorQuestions[fIndex];if(!x)return;document.querySelector('#question-number3').textContent=(fIndex+1)+' / 10';document.querySelector('#level3').textContent=dict().level[x.l];document.querySelector('#question3').textContent=x.q[lang()];const box=document.querySelector('#answers3');box.innerHTML='';x.a.forEach((answer,i)=>{const b=document.createElement('button');b.textContent=Array.isArray(answer)?answer[lang()]:answer;b.addEventListener('click',()=>chooseFactor(i,b));box.appendChild(b)});document.querySelector('#feedback3').textContent='';document.querySelector('#feedback3').className='';document.querySelector('#next3').hidden=true;fAnswered=false}
function chooseFactor(choice,button){if(fAnswered)return;fAnswered=true;const x=factorQuestions[fIndex],ok=choice===x.c;if(ok)fScore++;document.querySelector('#score3').textContent=fScore;[...document.querySelectorAll('#answers3 button')].forEach((b,i)=>{b.disabled=true;if(i===x.c)b.classList.add('correct-answer')});if(!ok)button.classList.add('wrong-answer');const f=document.querySelector('#feedback3');f.textContent=(ok?dict().correct:dict().wrong)+' '+x.e[lang()];f.className=ok?'correct':'wrong';const n=document.querySelector('#next3');n.textContent=fIndex===9?dict().finish:dict().next;n.hidden=false}
function nextFactor(){if(fIndex<9){fIndex++;renderFactor()}else{document.querySelector('#question-card3').hidden=true;document.querySelector('#result3').hidden=false;document.querySelector('#result-title3').textContent=dict().resultTitle;document.querySelector('#result-text3').textContent=fScore+'/10 — '+(fScore>=8?dict().resultGood:fScore>=5?dict().resultMid:dict().resultLow);document.querySelector('#restart3').textContent=dict().restart}}
function restartFactor(){fIndex=0;fScore=0;document.querySelector('#score3').textContent='0';document.querySelector('#result3').hidden=true;document.querySelector('#question-card3').hidden=false;renderFactor()}
document.querySelectorAll('[data-script]').forEach(b=>b.addEventListener('click',()=>{script=b.dataset.script;localStorage.setItem('matematikon-script',script);renderText()}));document.querySelector('#next').addEventListener('click',next);document.querySelector('#restart').addEventListener('click',restart);document.querySelector('#next2').addEventListener('click',nextPrime);document.querySelector('#restart2').addEventListener('click',restartPrime);document.querySelector('#next3').addEventListener('click',nextFactor);document.querySelector('#restart3').addEventListener('click',restartFactor);renderText();
